trial.program_source:
def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    for r in range(h):
        for c in range(w):
            if a[r][c]==2:
                sr,sc=r,c
    r,c=sr,sc
    a[r][c]=0
    while c<w-1:
        if a[r][c+1]==0:
            c+=1
        else:
            k=0
            rr=r
            while rr>=0 and a[rr][c+1]==3:
                k+=1
                rr-=1
            if 1<=k<=2 and c+2<w and a[r][c+2]==0:
                c+=2
            else:
                break
    a[r][c]=2
    if c==w-1:
        for rr,cc in [(0,w-2),(1,w-3),(1,w-2),(1,w-1),(2,w-2)]:
            if 0<=rr<h and 0<=cc<w:
                a[rr][cc]=4
    return a

